{
  "next": null,
  "section": "catalog",
  "start": 0,
  "text": "{
  "format": "craftmine.capabilities/1",
  "runtime": "craftmine-web/5",
  "entry": {
    "export": "step",
    "signature": "async step({frame, params, state}) => {state, commands}",
    "module": "ES 模块，必须导出 step"
  },
  "events": [
    {
      "type": "start",
      "payload": {},
      "note": "模块装载时一次，用来注册物品和面板"
    },
    {
      "type": "tick",
      "payload": {
        "dt": "秒"
      },
      "note": "每帧一次，返回的 commands 最多 32 条"
    },
    {
      "type": "interact",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家按 E 指向声明过的目标"
    },
    {
      "type": "contact",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家接触声明过的目标"
    },
    {
      "type": "attack",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家攻击命中声明过的目标"
    },
    {
      "type": "land",
      "payload": {
        "targetId": "对象 ID"
      },
      "note": "玩家落在声明过的目标上"
    },
    {
      "type": "key",
      "payload": {
        "code": "keys 中声明过的按键代码"
      },
      "note": "只有模块在 keys 里声明过的按键才会触发；不要读 frame.keys"
    }
  ],
  "keys": [
    "KeyB",
    "KeyC",
    "KeyG",
    "KeyH",
    "KeyI",
    "KeyJ",
    "KeyK",
    "KeyL",
    "KeyM",
    "KeyN",
    "KeyO",
    "KeyP",
    "KeyQ",
    "KeyU",
    "KeyV",
    "KeyX",
    "KeyY",
    "KeyZ",
    "Digit3",
    "Digit4",
    "Digit5",
    "Digit6",
    "Digit7",
    "Digit8",
    "Digit9"
  ],
  "permissions": [
    "objects.write",
    "player.motion",
    "hud.message",
    "inventory.write",
    "audio.play",
    "targets.write",
    "resources.write",
    "health.write"
  ],
  "capabilities": [
    "inventory.read@1",
    "inventory.items@1",
    "hud.panel@1"
  ],
  "requires": [
    "health@1",
    "ranged@1",
    "melee@1",
    "resource@1"
  ],
  "commands": [
    {
      "type": "object.patch",
      "permission": "objects.write",
      "scope": "声明过的 targets 里的对象",
      "fields": [
        {
          "name": "id",
          "description": "对象 ID"
        },
        {
          "name": "position",
          "description": "{x,y,z} 或 null；整项省略等同 null（保留原值）"
        },
        {
          "name": "visible",
          "description": "boolean 或 null"
        },
        {
          "name": "solid",
          "description": "boolean 或 null"
        },
        {
          "name": "color",
          "description": "'#RRGGBB' 或 null"
        },
        {
          "name": "yaw",
          "description": "null 或 0/90/180/270"
        },
        {
          "name": "duration",
          "description": "可选 0..5 秒，平滑移动"
        }
      ],
      "quota": "每步最多 32 条命令",
      "example": "{type:'object.patch',id:'door-1',visible:false}",
      "note": "visible:true 不会让已死亡的目标重新生效，复活必须用 target.revive"
    },
    {
      "type": "player.impulse",
      "permission": "player.motion",
      "scope": "当前玩家",
      "fields": [
        {
          "name": "velocity",
          "description": "{x,y,z}，每轴 -18..18"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'player.impulse',velocity:{x:0,y:8,z:0}}"
    },
    {
      "type": "hud.message",
      "permission": "hud.message",
      "scope": "当前玩家",
      "fields": [
        {
          "name": "text",
          "description": "最多 160 字纯文本"
        },
        {
          "name": "tone",
          "description": "可选 'info' | 'warn' | 'success'"
        },
        {
          "name": "duration",
          "description": "可选 1000..10000 毫秒"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'hud.message',text:'门开了',tone:'success'}"
    },
    {
      "type": "audio.play",
      "permission": "audio.play",
      "scope": "当前玩家",
      "fields": [
        {
          "name": "sound",
          "description": "'shoot' | 'hit' | 'open' | 'pickup' | 'error' | 'jump' | 'land' | 'step' | 'explode' | 'heal' | 'hurt' | 'unlock' | 'deny' | 'win'"
        },
        {
          "name": "volume",
          "description": "可选 0..1"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'audio.play',sound:'explode',volume:0.8}",
      "note": "使用宿主内置音效，不需要素材"
    },
    {
      "type": "target.revive",
      "permission": "targets.write",
      "scope": "声明过的 targets 里的目标",
      "fields": [
        {
          "name": "id",
          "description": "目标 ID"
        }
      ],
      "quota": "每步最多 16 个目标",
      "example": "{type:'target.revive',id:'zombie-1'}",
      "note": "把血量恢复到上限并重建模型；这是唯一能让已死亡目标复活的方式"
    },
    {
      "type": "resource.add",
      "permission": "resources.write",
      "scope": "场景里 type 为 resource 的玩家资源",
      "fields": [
        {
          "name": "id",
          "description": "资源系统 ID"
        },
        {
          "name": "amount",
          "description": "整数 -10000..10000"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'resource.add',id:'system-stamina',amount:-15}",
      "note": "结果自动夹在 0 到该系统 max 之间；体力、魔法、饥饿、护甲都用它"
    },
    {
      "type": "resource.set",
      "permission": "resources.write",
      "scope": "场景里 type 为 resource 的玩家资源",
      "fields": [
        {
          "name": "id",
          "description": "资源系统 ID"
        },
        {
          "name": "value",
          "description": "0..10000"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'resource.set',id:'system-mana',value:0}"
    },
    {
      "type": "health.add",
      "permission": "health.write",
      "scope": "当前玩家生命值",
      "fields": [
        {
          "name": "amount",
          "description": "整数 -10000..10000；正数治疗、负数扣血"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'health.add',amount:-12}",
      "note": "结果夹在 0 到血量上限之间；需要玩家生命值系统"
    },
    {
      "type": "target.damage",
      "permission": "targets.write",
      "scope": "声明过的 targets 里的目标",
      "fields": [
        {
          "name": "id",
          "description": "目标 ID"
        },
        {
          "name": "amount",
          "description": "0..10000"
        }
      ],
      "quota": "每步最多 16 个目标",
      "example": "{type:'target.damage',id:'zombie-1',amount:8}",
      "note": "直接扣目标血量；血量归零后模型消失，复活仍必须用 target.revive"
    },
    {
      "type": "inventory.add",
      "permission": "inventory.write",
      "scope": "当前玩家背包",
      "fields": [
        {
          "name": "item",
          "description": "稳定英文 ID（小写字母开头）"
        },
        {
          "name": "count",
          "description": "整数 -100..100"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'inventory.add',item:'wood',count:3}"
    },
    {
      "type": "inventory.define",
      "permission": "inventory.write",
      "capability": "inventory.items@1",
      "scope": "当前玩家背包",
      "fields": [
        {
          "name": "item",
          "description": "稳定英文 ID"
        },
        {
          "name": "name",
          "description": "最多 40 字"
        },
        {
          "name": "description",
          "description": "最多 200 字"
        }
      ],
      "quota": "每步最多 1 条",
      "example": "{type:'inventory.define',item:'wood',name:'木材',description:'用于制作'}",
      "note": "按稳定 ID 注册显示名称；第一次已提交的定义保留，后续同 ID 定义不覆盖；不能在 start 重复发放物品"
    },
    {
      "type": "hud.panel",
      "permission": "hud.message",
      "capability": "hud.panel@1",
      "scope": "当前模块自己的面板",
      "fields": [
        {
          "name": "key",
          "description": "面板 ID"
        },
        {
          "name": "panel",
          "description": "{title:'最多 48 字',lines:['最多 6 行，每行 120 字']} 或 null（删除）"
        }
      ],
      "quota": "每个模块最多 3 个面板",
      "example": "{type:'hud.panel',key:'quest',panel:{title:'任务',lines:['采集木材 1 / 3']}}",
      "note": "纯文本，按 key 替换本模块面板，不能操作别的模块面板；只在状态改变时更新"
    }
  ],
  "extensions": [],
  "systems": [
    {
      "type": "health",
      "name": "生命值",
      "dependencies": [
        "player@1"
      ],
      "fields": [
        {
          "name": "maxHealth",
          "min": 1,
          "max": 10000
        },
        {
          "name": "fallDamage",
          "min": 0,
          "max": 100
        },
        {
          "name": "regenPerSecond",
          "min": 0,
          "max": 100
        }
      ]
    },
    {
      "type": "ranged",
      "name": "射击",
      "dependencies": [
        "raycast@1",
        "damageable@1"
      ],
      "fields": [
        {
          "name": "damage",
          "min": 1,
          "max": 1000
        },
        {
          "name": "range",
          "min": 1,
          "max": 80
        },
        {
          "name": "cooldown",
          "min": 0.1,
          "max": 10
        },
        {
          "name": "magazine",
          "min": 1,
          "max": 100
        },
        {
          "name": "reloadSeconds",
          "min": 0.2,
          "max": 10
        }
      ]
    },
    {
