      "dependencies": [
        "player@1"
      ],
      "fields": [
        {
          "name": "max",
          "min": 1,
          "max": 10000
        },
        {
          "name": "regenPerSecond",
          "min": 0,
          "max": 100
        },
        {
          "name": "start",
          "min": 0,
          "max": 10000
        }
      ]
    }
  ],
  "materials": [
    "grass",
